INSERT INTO `v1_42461f68abc336e7d6c58dec840969fec1bc77983a5766f50230de57d97eb6d7` VALUES (72, 11, 0, 10, "だからわたし、\n勇気を出して言ってみたんです！\nお友だちになりませんか、って。", 1, 0, 1, 0, 1, 72021);
INSERT INTO `v1_42461f68abc336e7d6c58dec840969fec1bc77983a5766f50230de57d97eb6d7` VALUES (72, 91, "", 0, "", 0, "", 0, "", "", 72022);
