INSERT INTO `v1_42461f68abc336e7d6c58dec840969fec1bc77983a5766f50230de57d97eb6d7` VALUES (82, 11, 0, 10, "……別れ際に、\n「また誘うわね～♪」と、\n同じく柔和な笑顔でおっしゃって\nおられたのがやや気にはなりますが……", 1, 0, 1, 0, 1, 82033);
