INSERT INTO `v1_42461f68abc336e7d6c58dec840969fec1bc77983a5766f50230de57d97eb6d7` VALUES (142, 11, 0, 10, "……でも。\n今回の冒険で、夢見ることは\n大きな力だと知りましたから。", 1, 0, 1, 0, 1, 142024);
